#!/usr/bin/env ruby

require 'json'
require 'open-uri'
require 'nokogiri'

# Finance golden test for mwe004 (Cost & Resource Project)
# Generates golden JSON from the overview taskreport generated by tj3.
#
# IMPORTANT: this script parses `overview.html` (taskreport), NOT
# `PnL.html`/`Resources.html` (accountreport/resourcereport). The latter
# produce zero turnover when accounts use `aggregate tasks` because
# AccountScenario.turnover() short-circuits on container accounts. See
# project/aggregate-tasks-zero-cost.md.
#
# Usage: ruby scripts/golden/finance-mwe004.rb

OUTPUT_FILE = File.expand_path("../../packages/core/tests/golden/finance-mwe004.golden.json", __dir__)
TJP_PATH = File.expand_path("../../docs/Learning/mwe004/tutorial.tjp", __dir__)
OUTPUT_DIR = File.expand_path("../../packages/core/tests/golden", __dir__)

puts "Running tj3 on mwe004/tutorial.tjp..."
Dir.mkdir(OUTPUT_DIR, 0755) rescue nil

result = system("cd #{File.dirname(TJP_PATH)} && tj3 #{TJP_PATH} -o #{OUTPUT_DIR}")
if !result
  puts "ERROR: tj3 failed to generate reports"
  exit 1
end

# Parse overview.html (taskreport: WBS, Name, Start, End, Effort, Cost, Revenue)
overview_path = File.join(OUTPUT_DIR, "overview.html")
overview_doc = Nokogiri::HTML(File.read(overview_path))

# Parse resourceGraph.html (resourcereport: No., Name, Effort, Rate, weekly)
resource_path = File.join(OUTPUT_DIR, "resourceGraph.html")
resource_doc = Nokogiri::HTML(File.read(resource_path))

# TJ uses European number formatting: comma as decimal, dot as thousands.
# e.g. "36526,25" = 36526.25, "21000,00" = 21000.00
def parse_number(text)
  return 0.0 if text.nil? || text.strip.empty?
  # Remove thousands dots, replace comma with dot
  cleaned = text.gsub(/[^\d,.\-]/, "").gsub(".", "").tr(",", ".")
  cleaned.to_f
end

# Parse TJ effort strings like "4.0w" (weeks), "2.5m" (months), "3.0d" (days)
# into a numeric value in days. TJ loadunit is days.
# NOTE: effort values use dot as DECIMAL (e.g. "4.0d"), NOT thousands separator.
def parse_effort(text)
  return 0.0 if text.nil? || text.strip.empty?
  cleaned = text.strip
  # Match number + optional unit suffix
  if cleaned =~ /^([\d\.]+)([wdmhy])?$/
    value = $1.to_f
    unit = $2 || "d"
    case unit
    when "d" then value
    when "w" then value * 7.0
    when "m" then value * 30.0
    when "h" then value / 8.0
    else value
    end
  else
    0.0
  end
end

# Extract task rows from overview.html.
# Each <tr class="tabline"> has 7 <td> cells:
#   [0] WBS, [1] Name, [2] Start, [3] End, [4] Effort, [5] Cost, [6] Revenue
cases = []

overview_doc.xpath('//table[@class="tj_table"]//tr[@class="tabline"]').each do |row|
  cells = row.xpath('./td')
  next if cells.length < 7

  wbs = cells[0].text.strip
  name = cells[1].text.strip
  effort = parse_number(cells[4].text)
  cost = parse_number(cells[5].text)
  revenue = parse_number(cells[6].text)

  next if name.empty?

  cases << {
    "description" => "#{name} (WBS #{wbs})",
    "method" => "to_tjp",
    "type" => "Task",
    "input" => { "value" => nil },
    "expected" => {
      "effort" => effort,
      "cost" => cost,
      "revenue" => revenue,
      "balance" => revenue - cost,
      "turnover" => cost + revenue
    }
  }
end

# Extract resource rows from resourceGraph.html.
# Each resource row has 4 <td> cells with class resourcecell1 or resourcecell2:
#   [0] No., [1] Name (icon + label), [2] Effort (e.g. "4.0w"), [3] Rate (e.g. "350,00")
# The resource group row ("Developers") is skipped.
resource_doc.xpath('//table[@class="tj_table"]//tr[@class="tabline"][td[@class="resourcecell1" or @class="resourcecell2"]]').each do |row|
  cells = row.xpath('./td[@class="resourcecell1" or @class="resourcecell2"]')
  next if cells.length < 4

  # Name is the last <td class="tj_table_cell_label"> in the name cell
  name_cell = cells[1].xpath('.//td[@class="tj_table_cell_label"]')
  next if name_cell.empty?
  name = name_cell.last.text.strip
  # Skip the resource group row
  next if name == "Developers" || name.empty?

  effort_text = cells[2].xpath('.//td[@class="tj_table_cell_label"]').last.text.strip
  effort = parse_effort(effort_text)
  rate = parse_number(cells[3].xpath('.//td[@class="tj_table_cell_label"]').last.text.strip)

  cases << {
    "description" => "Resource: #{name}",
    "method" => "to_tjp",
    "type" => "Resource",
    "input" => { "value" => nil },
    "expected" => {
      "effort" => effort,
      "rate" => rate,
      "cost" => effort * rate,
      "revenue" => 0.0,
      "balance" => -(effort * rate),
      "turnover" => effort * rate
    }
  }
end

# Create golden JSON structure
# (sem `generated_at` — timestamp de wall-clock quebraria a idempotência do golden)
golden = {
  "version" => "1.0",
  "description" => "Casos financeiros extraídos de mwe004/tutorial.tjp (overview taskreport + resourceGraph resourcereport)",
  "cases" => cases
}

# Output JSON to stdout for capture by generate_golden.ts
# (log messages go to stderr so they don't pollute the JSON output)
$stderr.puts "Generated #{OUTPUT_FILE} with #{cases.length} cases"
$stderr.puts "Tasks: #{cases.select { |c| c["type"] == "Task" }.length}, Resources: #{cases.select { |c| c["type"] == "Resource" }.length}"
puts JSON.pretty_generate(golden)